/**
 * Unit tests for MathUtils.lcm(int, int)
 */
public class MathUtils_lcm_TriageGen0Test {







    @Test
    public void testLcmPositiveNumbers() {
        // Standard case: lcm(4, 6) = 12
        assertEquals(12, MathUtils.lcm(4, 6));
        // Standard case: lcm(7, 5) = 35 (coprime)
        assertEquals(35, MathUtils.lcm(7, 5));
        // Standard case: lcm(10, 10) = 10
        assertEquals(10, MathUtils.lcm(10, 10));
    }




}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
