import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.lcm(int, int)
 */
public class MathUtils_lcm_TriageGen0Test {









    @Test
    public void testLcmWithNegativeNumbers() {
        // Tests Math.abs logic: lcm(-4, 6) should be 12
        assertEquals(12, MathUtils.lcm(-4, 6));
        // lcm(4, -6) should be 12
        assertEquals(12, MathUtils.lcm(4, -6));
        // lcm(-4, -6) should be 12
        assertEquals(12, MathUtils.lcm(-4, -6));
    }


}

