/**
 * Unit tests for MathUtils.lcm(int, int)
 */
public class MathUtils_lcm_TriageGen0Test {











    @Test
    public void testLcmLargeValues() {
        // Testing values that are not extremely large but require proper calculation
        // lcm(21, 6) -> gcd is 3. (21/3)*6 = 7*6 = 42
        assertEquals(42, MathUtils.lcm(21, 6));
    }
